insert into public.quote_model_sets (id, country_code, currency_code, version, taxes_included, tax_note, suggested_tax_percent, suggested_tax_label, suggested_tax_reference, methodology, sources, disclaimer, valid_from) values ('br-2026-12', 'BR', 'BRL', '2026-12', true, 'Valor final ao cliente, impostos já inclusos.', null, null, null, 'Edição revista a pedido do dono do aplicativo. Os preços recomendados passaram a seguir a média nacional publicada pelos guias de preço de 2026 (antes: capitais do Sudeste), e foram acrescentados serviços em todas as categorias. Para cada serviço revisto ou novo foi usado o valor central da faixa publicada pela fonte indicada; os serviços sem nova fonte mantêm o valor da edição anterior. A tabela de eletricista indica só mão de obra (material à parte). Referências comerciais, não tabelas oficiais.', array['Cronoshare – guias de preço “Quanto custa” 2026, média nacional por serviço (cronoshare.com.br/quanto-custa)', 'Engehall – tabela de preços de eletricista 2026 (fev/2026), só mão de obra', 'Lar Pontual / Portal da Reforma – tabelas de encanador, reboco e contrapiso 2026', 'Cidesp – tabelas de mão de obra de pedreiro e hidráulica 2026', 'Catraca Livre, Monitor do Mercado e Diário do Comércio – diaristas, pedreiro e embreagem (2026)', 'Webmotors, Porto Seguro Centro Automotivo e Vrum – troca de óleo, pastilhas e fluido de câmbio', 'Idec – custo da hora em oficina independente', 'Edição 2026-11 (SINAPI/Caixa, SICRO/DNIT, Casamentos.com.br, Superprof e outras) – serviços sem nova fonte'], 'Valores indicativos. Cada profissional deve validar com seus custos reais (hora, impostos, combustível, margem) antes de publicar. Não constitui orientação contábil ou fiscal.', '2026-11-24');
